/* ===== 잼 무대: 소리 없이 박자와 코드 진행만 보여준다 ===== */
const KEYS={C:0,Db:1,'C#':1,D:2,Eb:3,'D#':3,E:4,F:5,Gb:6,'F#':6,G:7,Ab:8,'G#':8,A:9,Bb:10,'A#':10,B:11}, NAMES=['C','Db','D','Eb','E','F','Gb','G','Ab','A','Bb','B'];
/* 누구나 쓰는 공용 진행만 사용: [키에서의 반음, 종류] 한 마디씩 */
const FORMS={ '블루스 12마디':[[0,'7'],[5,'7'],[0,'7'],[0,'7'],[5,'7'],[5,'7'],[0,'7'],[9,'7'],[2,'m7'],[7,'7'],[0,'7'],[7,'7']], '투파이브원 8마디':[[2,'m7'],[7,'7'],[0,'M7'],[0,'M7'],[2,'m7'],[7,'7'],[0,'M7'],[9,'7']], '마이너 블루스 12마디':[[0,'m7'],[0,'m7'],[0,'m7'],[0,'m7'],[5,'m7'],[5,'m7'],[0,'m7'],[0,'m7'],[8,'7'],[7,'7'],[0,'m7'],[7,'7']], '모달 8마디':[[0,'m7'],[0,'m7'],[0,'m7'],[0,'m7'],[1,'m7'],[1,'m7'],[0,'m7'],[0,'m7']] };
const jam={on:false}, clockNow=()=>performance.now()/1000;
const PADS=['A','S','D','F','G','H','J','K'], DRN=['킥','스네어','하이햇','라이드','탐1','탐2','크래시','벨'];
function scaleNow(){ const [r,q]=jam.form[jam.bar%jam.form.length], root=jam.key+r, sc=q==='M7'?[0,2,4,7,9,11]:q==='m7'?[0,2,3,5,7,9,10]:[0,2,3,4,7,9,10]; const base={베이스:36,기타:55,피아노:60,색소폰:58,보컬:60}[jam.part]||60, out=[]; for(let m=base;out.length<8;m++) if(sc.includes(((m-root)%12+12)%12)) out.push(m); return out; }
const chName=([r,q])=>NAMES[(jam.key+r)%12]+(q==='M7'?'maj7':q);
function jamHit(i){ if(!jam.on||!jam.part)return; const t=clockNow(); jam.notes++; jam.bounce[jam.part]=1; const p=document.querySelectorAll('#jam .pad')[i]; if(p){p.classList.add('hit');setTimeout(()=>p.classList.remove('hit'),110);}
  const b=60/jam.bpm, ph=((t-jam.t0)%(b)+b)%b, off=Math.min(Math.abs(ph),Math.abs(ph-b),Math.abs(ph-b*2/3)); jam.good+=off<b*.13?1:0; noteFx(); }
function tick(){ if(!jam.on)return; const b=60/jam.bpm; while(jam.next<=clockNow()){ jam.bar=jam.beat/4|0; jam.show=jam.beat; jam.band.forEach(p=>jam.bounce[p]=1); jamUi(); jam.beat++; jam.next+=b; } jam.timer=setTimeout(tick,25); }
function jamUi(){ const el_=document.getElementById('jam'); el_.querySelectorAll('.bar').forEach((n,i)=>n.classList.toggle('now',i===jam.bar%jam.form.length)); el_.querySelectorAll('.dot').forEach((n,i)=>n.classList.toggle('now',i===jam.show%4)); if(jam.part&&jam.part!=='드럼'){ const s=scaleNow(); el_.querySelectorAll('.pad small').forEach((n,i)=>n.textContent=NAMES[s[i]%12]); } }
function startJam(j,owner){ stopJam(); const my=j.slots.find(s=>s.who===ME); const km=/^([A-G][b#]?)/.exec(j.key||'')||[0,'F']; Object.assign(jam,{on:true,j,owner,part:my?my.part:null,band:j.slots.filter(s=>s.who&&s.who!==ME).map(s=>s.part),key:KEYS[km[1]]??5,bpm:jam.bpm||128,formName:jam.formName||(/m$/.test(j.key||'')?'마이너 블루스 12마디':'블루스 12마디'),beat:0,bar:0,show:0,next:clockNow()+.25,t0:clockNow()+.25,notes:0,good:0,bounce:{}}); jam.form=FORMS[jam.formName];
  hide(); stageCast(j); drawJam(); resize(); tick(); }
function stopJam(msg){ if(!jam.on)return; jam.on=false; clearTimeout(jam.timer); document.getElementById('jam').classList.remove('on'); resize(); cafe.npcs=cafe.npcs.filter(n=>!n.stage); if(scene===cafe){ warp(cafe,...cafe.start,3); } if(msg&&jam.part&&jam.notes){ const n=jam.notes,part=jam.part,lines=ok=>[`${part}: ${n}음을 연주했다.`,jam.good/n>.6?'박자에 착 감기는 연주! 객석에서 박수가 터진다.':'자유로운 연주였다. 한 번 더 해 볼까?',...(ok?['이 잼은 Groov 아카이브의 잼 기록에 남았다.']:[])]; if(cloud.member&&jam.j.id) asMember(()=>rpc('finish_song',{p_song:jam.j.id}),()=>say('잼이 끝났다',lines(true))); else say('잼이 끝났다',lines(false)); } }
function drawJam(){ const J=document.getElementById('jam'), sel=(o,v,f)=>el('select',{onchange:e=>f(e.target.value)},...o.map(x=>el('option',{value:x,textContent:x,selected:x===v})));
  J.replaceChildren(el('div',{cls:'jtop'},el('b',{textContent:`♪ ${jam.j.title}`}),el('span',{cls:'sub',textContent:jam.part?`내 자리: ${jam.part}`:'관객으로 보는 중'}),el('span',{cls:'dots'},...[0,1,2,3].map(()=>el('i',{cls:'dot'}))),sel(Object.keys(FORMS),jam.formName,v=>{jam.formName=v;jam.form=FORMS[v];jam.beat=0;drawJam();}),el('label',{cls:'bpm'},'빠르기',el('input',{type:'range',min:70,max:220,value:jam.bpm,oninput:e=>{jam.bpm=+e.target.value;}})),btn('끝내기',()=>stopJam(true))),
    el('div',{cls:'bars'},...jam.form.map(c=>el('span',{cls:'bar',textContent:chName(c)}))),
    jam.part?el('div',{cls:'pads'},...PADS.map((k,i)=>el('button',{cls:'pad',type:'button',onpointerdown:e=>{e.preventDefault();jamHit(i);}},el('b',{textContent:k}),el('small',{textContent:jam.part==='드럼'?DRN[i]:''})))):el('div',{cls:'sub',textContent:'빈자리에 신청하면 함께 연주할 수 있어요.'}));
  J.classList.add('on'); jamUi(); document.activeElement?.blur(); }
function stageCast(j){ if(scene!==cafe) warp(cafe,...cafe.start,3); cafe.npcs=cafe.npcs.filter(n=>!n.stage); j.slots.forEach((s,i)=>{ const p=STAGE[s.part]; if(!p||!s.who)return; if(s.who===ME){ me.tx=p[0];me.ty=p[1];me.px=p[0]*T;me.py=p[1]*T;me.dir=p[2];me.moving=false;route=[];after=null; } else { const n=actor(p[0],p[1],lookFor(s.who),{name:nm(s.who),lines:['지금은 연주 중!'],stage:s.part,home:p,range:0}); n.dir=p[2]; cafe.npcs.push(n); } }); }
